from collections import Counter,deque
def shapes(G):
    bg=Counter(x for r in G for x in r).most_common(1)[0][0]
    H,W=len(G),len(G[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if G[i][j]!=bg and not seen[i][j]:
                col=G[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and G[x][y]==col and not seen[x][y]:
                                seen[x][y]=True;q.append((x,y))
                # bounding box
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                out.append((col,(min(rs),max(rs),min(cs),max(cs)),sorted(cells)))
    return bg,out
