def slide(gi):
    bg=Counter(x for r in gi for x in r).most_common(1)[0][0]
    H=len(gi); W=len(gi[0])
    O=comps(gi,bg)
    cnt={}
    for c,cl in O: cnt.setdefault(c,[]).append(cl)
    erase=max(cnt,key=lambda c:len(cnt[c]))
    occs=[]; colors=[]
    for c,cls in cnt.items():
        if c!=erase: occs.append(set(cls[0])); colors.append(c)
    for cell in cnt[erase]:
        for r0,c0 in cell:
            best=min(range(len(occs)),key=lambda j:min(max(abs(r0-a),abs(c0-b)) for a,b in occs[j]))
            occs[best].add((r0,c0))
    # each object slides diagonally down-left until blocked (by another or edge) — one-shot per object, order by top row
    order=sorted(range(len(occs)), key=lambda j:min(r for r,_ in occs[j]))
    placed=set()
    results=[]
    for i in order:
        cs=occs[i]; occupied={p for j in range(len(occs)) if j!=i for p in occs[j]}
        pos=list(cs)
        dr=1; dc=-1; moved=True
        while moved:
            npo=[(r+dr,c+dc) for r,c in pos]
            if any(not(0<=a<H and 0<=b<W) for a,b in npo) or set(npo)&occupied: break
            pos=npo
        occs[i]=pos; results.append(pos)
    return occs,colors
