def comps(g,bg=None):
    H=len(g); W=len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; cl=set()
                while stack:
                    r,c=stack.pop()
                    if (r,c) in seen: continue
                    seen.add((r,c)); cl.add((r,c))
                    for dr in (-1,0,1):
