                nc={(r-1,c-1) for r,c in cur[i]}
                if nc & cur[j]: ok=False; break
            if ok and min(r for r,_ in nc)>=0 and min(c for _,c in nc)>=0:
                nxt[i]=nc; moved=True
            else:
                nxt[i]=cur[i]
        if moved: cur=nxt
        else: break
    # crop columns
    mins=[min(c for _,c in cs) for cs in cur.values()]
    maxc=max(max(c for _,c in cs) for cs in cur.values())
