def f(g):
    H=len(g); W=len(g[0]); bg=3
    comp={}
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v!=bg and (i,j) not in comp:
                stack=[(i,j)]; cid=len(comp); comp[(i,j)]=cid
                while stack:
                    a,b=stack.pop()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]!=bg and (x,y) not in comp:
                                comp[(x,y)]=cid; stack.append((x,y))
    objs=[]
    for c in comp.values():
        cells=[(i,j) for (i,j) in comp if comp[(i,j)]==c]
        objs.append((g[cells[0][0]][cells[0][1]],set(cells),len(cells)>=2))
    multi=[o for o in objs if o[2]>=2]
    singles=[(g[r][c],r,c) for o in objs if o[2]<2 for r,c in o[1]]
    cur={i:set(multi[i][1]) for i in range(len(multi))}
    for col,r,c in singles:
        j=min(range(len(multi)),key=lambda i:min(abs(r-a)+abs(c-b) for a,b in cur[i]))
        cur[j].add((r,c))
    def step(cs,others,H,W):
        nc={(a-1,b-1) for a,b in cs}
        if min(a for a,_ in nc)<0 or min(b for _,b in nc)<0: return None
        if nc & others: return None
        if any(abs(a-x)<=1 and abs(b-y)<=1 for a,b in nc for x,y in others): return None
        return nc
    changed=True
    while changed:
        changed=False
        for i in sorted(cur):
            oth={(a,b) for j in cur if j!=i for a,b in cur[j]}
            r=step(cur[i],oth,H,W)
            if r is not None:
                cur[i]=r; changed=True
    # crop: min row and min col of content
    r0=min(a for cs in cur.values() for a,b in cs)
    c0=min(b for cs in cur.values() for a,b in cs)
    h=max(a for cs in cur.values() for a,b in cs)-r0+1
    w=max(b for cs in cur.values() for a,b in cs)-c0+1
    res=[[3]*w for _ in range(h)]
    for i,cs in cur.items():
        col=multi[i][0]
        for a,b in cs: res[a-r0][b-c0]=col
    return [row[:] for row in res]

